/**
 * Process export request (right to data portability).
 * Queries all user-related data from the database and returns it as a
 * JSON bundle.
 */
private async processExportRequest(request: DataSubjectRequest): Promise<DataSubjectResult> {
  // Collect in-memory records
  const inMemoryRecords = this.getRecordsForSubject(request.orgId, request.subjectId);

  // Collect real DB records for the subject
  let dbUserData: Record<string, unknown>[] = [];
  let dbAuditData: Record<string, unknown>[] = [];
  let dbConversationData: Record<string, unknown>[] = [];
  let dbEmotionalData: Record<string, unknown>[] = [];

  try {
    const db = await getDb();

    // User profile data (match by email or openId)
    dbUserData = await db
      .select()
      .from(users)
      .where(eq(users.email, request.subjectEmail));

    // Governance audit log entries for the subject
    if (dbUserData.length > 0) {
      const userId = (dbUserData[0] as any).id;
      dbAuditData = await db
        .select()
        .from(governanceAuditLog)
        .where(eq(governanceAuditLog.actorId, userId));

      dbConversationData = await db
        .select()
        .from(conversationSessions)
        .where(eq(conversationSessions.userId, userId));

      dbEmotionalData = await db
        .select()
        .from(emotionalHistory)
        .where(eq(emotionalHistory.userId, userId));
    }
  } catch (err) {
    // DB unavailable — proceed with in-memory data only
    this.logAudit("DSR_EXPORT_DB_PARTIAL", "system", `DB query failed during export: ${(err as Error).message}`, request.subjectId);
  }

  // Create export data bundle
  const exportData = {
    subjectId: request.subjectId,
    subjectEmail: request.subjectEmail,
    exportedAt: new Date().toISOString(),
    user_profile: dbUserData,
    audit_log: dbAuditData,
    conversations: dbConversationData,
    emotional_history: dbEmotionalData,
    retention_records: inMemoryRecords.map(r => ({
      category: r.dataCategory,
      data: r.data,
      createdAt: r.createdAt.toISOString(),
    })),
  };

  const exportUrl = `data:application/json;base64,${Buffer.from(JSON.stringify(exportData)).toString("base64")}`;
  const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days

  const totalRecords = dbUserData.length + dbAuditData.length + dbConversationData.length + dbEmotionalData.length + inMemoryRecords.length;

  return {
    exportUrl,
    exportExpiresAt: expiresAt,
    deletedRecords: 0,
    retainedRecords: totalRecords,
    retentionReason: null,
    verificationHash: crypto.createHash("sha256").update(JSON.stringify(exportData)).digest("hex"),
    completedAt: new Date(),
  };
}

/**
 * Process delete request (right to be forgotten).
 * Deletes user data from DB tables and in-memory records.
 */
private async processDeleteRequest(request: DataSubjectRequest): Promise<DataSubjectResult> {
  let deletedCount = 0;
  let retainedCount = 0;
  const retentionReasons: string[] = [];

  // ----- Delete from real DB tables -----
  try {
    const db = await getDb();

    // Find the user by email
    const userRows = await db
      .select()
      .from(users)
      .where(eq(users.email, request.subjectEmail));

    if (userRows.length > 0) {
      const userId = userRows[0].id;

      // Delete emotional history
      const emotionalDel = await db.delete(emotionalHistory).where(eq(emotionalHistory.userId, userId));
      deletedCount += (emotionalDel as any).rowCount ?? 0;

      // Delete emotional patterns
      const patternDel = await db.delete(emotionalPatterns).where(eq(emotionalPatterns.userId, userId));
      deletedCount += (patternDel as any).rowCount ?? 0;

      // Delete conversation turns for user's sessions
      const userSessions = await db.select().from(conversationSessions).where(eq(conversationSessions.userId, userId));
      for (const session of userSessions) {
        const turnDel = await db.delete(conversationTurns).where(eq(conversationTurns.sessionId, session.sessionId));
        deletedCount += (turnDel as any).rowCount ?? 0;
      }

      // Delete conversation sessions
      const sessionDel = await db.delete(conversationSessions).where(eq(conversationSessions.userId, userId));
      deletedCount += (sessionDel as any).rowCount ?? 0;

      // Delete API usage records
      const usageDel = await db.delete(apiUsage).where(eq(apiUsage.userId, userId));
      deletedCount += (usageDel as any).rowCount ?? 0;

      // Governance audit log: retain for compliance but anonymize
      const auditRows = await db
        .select()
        .from(governanceAuditLog)
        .where(eq(governanceAuditLog.actorId, userId));
      if (auditRows.length > 0) {
        retainedCount += auditRows.length;
        retentionReasons.push(`${auditRows.length} governance audit log entries: Compliance requirement — anonymized`);
        // Anonymize the actor field
        await db
          .update(governanceAuditLog)
          .set({ actor: "[DELETED_USER]" } as any)
          .where(eq(governanceAuditLog.actorId, userId));
      }

      // Delete the user record itself
      await db.delete(users).where(eq(users.id, userId));
      deletedCount += 1;
    }
  } catch (err) {
    this.logAudit("DSR_DELETE_DB_ERROR", "system", `DB deletion failed: ${(err as Error).message}`, request.subjectId);
    retentionReasons.push(`DB deletion error: ${(err as Error).message}`);
  }

  // ----- Delete in-memory records -----
  const inMemoryRecords = this.getRecordsForSubject(request.orgId, request.subjectId);
  for (const record of inMemoryRecords) {
    const policy = this.policies.get(record.retentionPolicyId);

    if (record.legalHold || policy?.legalHoldEnabled) {
      retainedCount++;
      retentionReasons.push(`Record ${record.recordId}: Legal hold`);
      continue;
    }

    if (record.dataCategory === "audit_logs" && policy?.complianceFramework !== "custom") {
      retainedCount++;
      retentionReasons.push(`Record ${record.recordId}: Compliance requirement`);
      continue;
    }

    record.deletedAt = new Date();

