tool_use_result.originalFile:
/**
 * Data Retention & GDPR Compliance System
 * 
 * Handles:
 * - Configurable retention policies
 * - Automatic data expiration
 * - GDPR data subject requests (export, delete)
 * - Audit trail preservation
 * - Right to be forgotten
 * 
 * "Proof data has a lifecycle"
 */

import crypto from "crypto";
import { getDb, DatabaseUnavailableError } from "../db";
import { eq, and } from "drizzle-orm";
import {
  dataSubjectRequests,
  users,
  governanceAuditLog,
  conversationSessions,
  conversationTurns,
  emotionalHistory,
  emotionalPatterns,
  apiUsage,
} from "../../drizzle/schema";

// ============================================================================
// TYPES
// ============================================================================

export interface RetentionPolicy {
  policyId: string;
  orgId: string;
  name: string;

  // Data categories
  dataCategory: "audit_logs" | "proofs" | "artifacts" | "user_data" | "analytics";

  // Retention settings
  retentionDays: number;
  archiveAfterDays: number | null;
  deleteAfterDays: number;

  // Legal hold
  legalHoldEnabled: boolean;
  legalHoldReason: string | null;

  // Compliance
  complianceFramework: "gdpr" | "ccpa" | "hipaa" | "sox" | "custom";

  // Status
  active: boolean;
  createdAt: Date;
  updatedAt: Date;
}

export interface DataSubjectRequest {
  requestId: string;
  orgId: string;

  // Subject identification
  subjectId: string;
  subjectEmail: string;

  // Request details
  requestType: "export" | "delete" | "access" | "rectify" | "restrict";
  requestedAt: Date;
  deadline: Date;

  // Status
  status: "pending" | "processing" | "completed" | "rejected";
  completedAt: Date | null;

  // Result
  result: DataSubjectResult | null;

  // Audit
  processedBy: string | null;
  notes: string;
}

export interface DataSubjectResult {
  // For export requests
  exportUrl: string | null;
  exportExpiresAt: Date | null;

  // For delete requests
  deletedRecords: number;
  retainedRecords: number;
  retentionReason: string | null;

  // Verification
  verificationHash: string;
  completedAt: Date;
}

export interface DataRecord {
  recordId: string;
  orgId: string;
  subjectId: string | null;

  // Data
  dataCategory: RetentionPolicy["dataCategory"];
  data: Record<string, unknown>;

  // Lifecycle
  createdAt: Date;
  expiresAt: Date;
  archivedAt: Date | null;
  deletedAt: Date | null;

  // Legal hold
  legalHold: boolean;

  // Metadata
  retentionPolicyId: string;
}

export interface ComplianceReport {
  reportId: string;
  orgId: string;

  // Coverage
  framework: RetentionPolicy["complianceFramework"];
  reportPeriod: { start: Date; end: Date };

  // Metrics
  totalRecords: number;
  expiredRecords: number;
  archivedRecords: number;
  deletedRecords: number;

  // DSR metrics
  totalDSRs: number;
  completedDSRs: number;
  averageResponseTime: number;

  // Issues
  issues: string[];
  recommendations: string[];

  // Generated
  generatedAt: Date;
  generatedBy: string;
}

// ============================================================================
// DATA RETENTION SERVICE
// ============================================================================

export class DataRetentionService {
  private policies: Map<string, RetentionPolicy> = new Map();
  private requests: Map<string, DataSubjectRequest> = new Map();
  private records: Map<string, DataRecord> = new Map();
  private auditLog: Array<{
    timestamp: Date;
    action: string;
    actor: string;
    details: string;
    subjectId: string | null;
  }> = [];

  // GDPR deadline (30 days)
  private dsrDeadlineDays = 30;

  // ============================================================================
  // RETENTION POLICIES
  // ============================================================================

  /**
   * Create a retention policy
   */
  createPolicy(params: {
    orgId: string;
    name: string;
    dataCategory: RetentionPolicy["dataCategory"];
    retentionDays: number;
    archiveAfterDays?: number;
    deleteAfterDays: number;
    complianceFramework: RetentionPolicy["complianceFramework"];
  }): RetentionPolicy {
    const policy: RetentionPolicy = {
      policyId: crypto.randomUUID(),
      orgId: params.orgId,
      name: params.name,
      dataCategory: params.dataCategory,
      retentionDays: params.retentionDays,
      archiveAfterDays: params.archiveAfterDays ?? null,
      deleteAfterDays: params.deleteAfterDays,
      legalHoldEnabled: false,
      legalHoldReason: null,
      complianceFramework: params.complianceFramework,
      active: true,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    this.policies.set(policy.policyId, policy);
    this.logAudit("POLICY_CREATED", "system", `Retention policy '${params.name}' created`, null);

    return policy;
  }

  /**
   * Get policies for an org
   */
  getPolicies(orgId: string): RetentionPolicy[] {
    return Array.from(this.policies.values()).filter(p => p.orgId === orgId);
  }

  /**
   * Enable legal hold on a policy
   */
  enableLegalHold(policyId: string, reason: string): RetentionPolicy {
    const policy = this.policies.get(policyId);
    if (!policy) {
      throw new Error(`Policy ${policyId} not found`);
    }

    policy.legalHoldEnabled = true;
    policy.legalHoldReason = reason;
    policy.updatedAt = new Date();

    this.logAudit("LEGAL_HOLD_ENABLED", "system", `Legal hold enabled on policy ${policyId}: ${reason}`, null);

    return policy;
  }

  /**
   * Disable legal hold on a policy
   */
  disableLegalHold(policyId: string): RetentionPolicy {
    const policy = this.policies.get(policyId);
    if (!policy) {
      throw new Error(`Policy ${policyId} not found`);
    }

    policy.legalHoldEnabled = false;
    policy.legalHoldReason = null;
    policy.updatedAt = new Date();

    this.logAudit("LEGAL_HOLD_DISABLED", "system", `Legal hold disabled on policy ${policyId}`, null);

    return policy;
  }

  // ============================================================================
  // DATA RECORDS
  // ============================================================================

  /**
   * Store a data record with retention
   */
  storeRecord(params: {
    orgId: string;
    subjectId?: string;
    dataCategory: RetentionPolicy["dataCategory"];
    data: Record<string, unknown>;
    policyId: string;
  }): DataRecord {
    const policy = this.policies.get(params.policyId);
    if (!policy) {
      throw new Error(`Policy ${params.policyId} not found`);
    }

    const now = new Date();
    const expiresAt = new Date(now.getTime() + policy.retentionDays * 24 * 60 * 60 * 1000);

    const record: DataRecord = {
      recordId: crypto.randomUUID(),
      orgId: params.orgId,
      subjectId: params.subjectId ?? null,
      dataCategory: params.dataCategory,
      data: params.data,
      createdAt: now,
      expiresAt,
      archivedAt: null,
      deletedAt: null,
      legalHold: policy.legalHoldEnabled,
      retentionPolicyId: params.policyId,
    };

    this.records.set(record.recordId, record);
    return record;
  }

  /**
   * Get records for a subject
   */
  getRecordsForSubject(orgId: string, subjectId: string): DataRecord[] {
    return Array.from(this.records.values())
      .filter(r => r.orgId === orgId && r.subjectId === subjectId && !r.deletedAt);
  }

  /**
   * Process expired records
   */
  processExpiredRecords(): {
    archived: number;
    deleted: number;
    retained: number;
  } {
    const now = new Date();
    let archived = 0;
    let deleted = 0;
    let retained = 0;

    for (const record of this.records.values()) {
      if (record.deletedAt) continue;

      const policy = this.policies.get(record.retentionPolicyId);
      if (!policy) continue;

      // Check legal hold
      if (record.legalHold || policy.legalHoldEnabled) {
        retained++;
        continue;
      }

      const ageMs = now.getTime() - record.createdAt.getTime();
      const ageDays = ageMs / (24 * 60 * 60 * 1000);

      // Check for deletion
      if (ageDays >= policy.deleteAfterDays) {
        record.deletedAt = now;
        deleted++;
        this.logAudit("RECORD_DELETED", "system", `Record ${record.recordId} deleted per policy`, record.subjectId);
        continue;
      }

      // Check for archival
      if (policy.archiveAfterDays && ageDays >= policy.archiveAfterDays && !record.archivedAt) {
        record.archivedAt = now;
        archived++;
        this.logAudit("RECORD_ARCHIVED", "system", `Record ${record.recordId} archived per policy`, record.subjectId);
      }
    }

    return { archived, deleted, retained };
  }

  // ============================================================================
  // DATA SUBJECT REQUESTS (GDPR)
  // ============================================================================

  /**
   * Create a data subject request — persists to DB and in-memory map.
   */
  async createDSR(params: {
    orgId: string;
    subjectId: string;
    subjectEmail: string;
    requestType: DataSubjectRequest["requestType"];
  }): Promise<DataSubjectRequest> {
    const now = new Date();
    const deadline = new Date(now.getTime() + this.dsrDeadlineDays * 24 * 60 * 60 * 1000);

    const request: DataSubjectRequest = {
      requestId: crypto.randomUUID(),
      orgId: params.orgId,
      subjectId: params.subjectId,
      subjectEmail: params.subjectEmail,
      requestType: params.requestType,
      requestedAt: now,
      deadline,
      status: "pending",
      completedAt: null,
      result: null,
      processedBy: null,
      notes: "",
    };

    // Persist to database
    try {
      const db = await getDb();
      if (!db) throw new DatabaseUnavailableError("Database unavailable: cannot persist DSR");
      await db.insert(dataSubjectRequests).values({
        id: request.requestId,
        orgId: request.orgId,
        subjectId: request.subjectId,
        subjectEmail: request.subjectEmail,
        requestType: request.requestType,
        status: request.status,
        deadline: request.deadline,
        notes: request.notes,
      });
    } catch (err) {
      // Log but don't fail — keep in-memory fallback
      this.logAudit("DSR_DB_WRITE_FAILED", "system", `Failed to persist DSR to DB: ${(err as Error).message}`, params.subjectId);
    }

    this.requests.set(request.requestId, request);
    this.logAudit("DSR_CREATED", "system", `DSR ${params.requestType} created for subject ${params.subjectId}`, params.subjectId);

    return request;
  }

  /**
   * Process a data subject request — performs real DB queries/deletes and
   * updates the DSR status in the database.
   */
  async processDSR(requestId: string, processedBy: string): Promise<DataSubjectRequest> {
    const request = this.requests.get(requestId);
    if (!request) {
      throw new Error(`DSR ${requestId} not found`);
    }

    if (request.status !== "pending") {
      throw new Error(`DSR ${requestId} is not pending`);
    }

    request.status = "processing";
    request.processedBy = processedBy;

    // Update DB status to "processing"
    await this.updateDSRInDb(requestId, { status: "processing", processedBy });

    // Process based on type
    switch (request.requestType) {
      case "export":
        request.result = await this.processExportRequest(request);
        break;
      case "delete":
        request.result = await this.processDeleteRequest(request);
        break;
      case "access":
        request.result = await this.processAccessRequest(request);
        break;
      case "restrict":
        request.result = await this.processRestrictRequest(request);
        break;
      case "rectify":
        // Rectification requires manual handling
        request.notes = "Rectification request requires manual review";
        break;
    }

    request.status = "completed";
    request.completedAt = new Date();

    // Update DB status to "completed"
    await this.updateDSRInDb(requestId, {
      status: "completed",
      completedAt: request.completedAt,
      result: request.result ? JSON.stringify(request.result) : null,
      notes: request.notes,
    });

    this.logAudit("DSR_COMPLETED", processedBy, `DSR ${request.requestType} completed for subject ${request.subjectId}`, request.subjectId);

    return request;
  }

  /**
   * Process export request (right to data portability).
   * Queries all user-related data from the database and returns it as a
   * JSON bundle.
   */
  private async processExportRequest(request: DataSubjectRequest): Promise<DataSubjectResult> {
    // Collect in-memory records
    const inMemoryRecords = this.getRecordsForSubject(request.orgId, request.subjectId);

    // Collect real DB records for the subject
    let dbUserData: Record<string, unknown>[] = [];
    let dbAuditData: Record<string, unknown>[] = [];
    let dbConversationData: Record<string, unknown>[] = [];
    let dbEmotionalData: Record<string, unknown>[] = [];

    try {
      const db = await getDb();
      if (!db) throw new DatabaseUnavailableError("Database unavailable: cannot query subject data for export");

      // User profile data (match by email or openId)
      dbUserData = await db
        .select()
        .from(users)
        .where(eq(users.email, request.subjectEmail));

      // Governance audit log entries for the subject
      if (dbUserData.length > 0) {
        const userId = (dbUserData[0] as any).id;
        dbAuditData = await db
          .select()
          .from(governanceAuditLog)
          .where(eq(governanceAuditLog.actorId, userId));

        dbConversationData = await db
          .select()
          .from(conversationSessions)
          .where(eq(conversationSessions.userId, userId));

        dbEmotionalData = await db
          .select()
          .from(emotionalHistory)
          .where(eq(emotionalHistory.userId, userId));
      }
    } catch (err) {
      // DB unavailable — proceed with in-memory data only
      this.logAudit("DSR_EXPORT_DB_PARTIAL", "system", `DB query failed during export: ${(err as Error).message}`, request.subjectId);
    }

    // Create export data bundle
    const exportData = {
      subjectId: request.subjectId,
      subjectEmail: request.subjectEmail,
      exportedAt: new Date().toISOString(),
      user_profile: dbUserData,
      audit_log: dbAuditData,
      conversations: dbConversationData,
      emotional_history: dbEmotionalData,
      retention_records: inMemoryRecords.map(r => ({
        category: r.dataCategory,
        data: r.data,
        createdAt: r.createdAt.toISOString(),
      })),
    };

    const exportUrl = `data:application/json;base64,${Buffer.from(JSON.stringify(exportData)).toString("base64")}`;
    const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days

    const totalRecords = dbUserData.length + dbAuditData.length + dbConversationData.length + dbEmotionalData.length + inMemoryRecords.length;

    return {
      exportUrl,
      exportExpiresAt: expiresAt,
      deletedRecords: 0,
      retainedRecords: totalRecords,
      retentionReason: null,
      verificationHash: crypto.createHash("sha256").update(JSON.stringify(exportData)).digest("hex"),
      completedAt: new Date(),
    };
  }

  /**
   * Process delete request (right to be forgotten).
   * Deletes user data from DB tables and in-memory records.
   */
  private async processDeleteRequest(request: DataSubjectRequest): Promise<DataSubjectResult> {
    let deletedCount = 0;
    let retainedCount = 0;
    const retentionReasons: string[] = [];

    // ----- Delete from real DB tables -----
    try {
      const db = await getDb();

      // Find the user by email
      const userRows = await db
        .select()
        .from(users)
        .where(eq(users.email, request.subjectEmail));

      if (userRows.length > 0) {
        const userId = userRows[0].id;

        // Delete emotional history
        const emotionalDel = await db.delete(emotionalHistory).where(eq(emotionalHistory.userId, userId));
        deletedCount += (emotionalDel as any).rowCount ?? 0;

        // Delete emotional patterns
        const patternDel = await db.delete(emotionalPatterns).where(eq(emotionalPatterns.userId, userId));
        deletedCount += (patternDel as any).rowCount ?? 0;

        // Delete conversation turns for user's sessions
        const userSessions = await db.select().from(conversationSessions).where(eq(conversationSessions.userId, userId));
        for (const session of userSessions) {
          const turnDel = await db.delete(conversationTurns).where(eq(conversationTurns.sessionId, session.sessionId));
          deletedCount += (turnDel as any).rowCount ?? 0;
        }

        // Delete conversation sessions
        const sessionDel = await db.delete(conversationSessions).where(eq(conversationSessions.userId, userId));
        deletedCount += (sessionDel as any).rowCount ?? 0;

        // Delete API usage records
        const usageDel = await db.delete(apiUsage).where(eq(apiUsage.userId, userId));
        deletedCount += (usageDel as any).rowCount ?? 0;

        // Governance audit log: retain for compliance but anonymize
        const auditRows = await db
          .select()
          .from(governanceAuditLog)
          .where(eq(governanceAuditLog.actorId, userId));
        if (auditRows.length > 0) {
          retainedCount += auditRows.length;
          retentionReasons.push(`${auditRows.length} governance audit log entries: Compliance requirement — anonymized`);
          // Anonymize the actor field
          await db
            .update(governanceAuditLog)
            .set({ actor: "[DELETED_USER]" } as any)
            .where(eq(governanceAuditLog.actorId, userId));
        }

        // Delete the user record itself
        await db.delete(users).where(eq(users.id, userId));
        deletedCount += 1;
      }
    } catch (err) {
      this.logAudit("DSR_DELETE_DB_ERROR", "system", `DB deletion failed: ${(err as Error).message}`, request.subjectId);
      retentionReasons.push(`DB deletion error: ${(err as Error).message}`);
    }

    // ----- Delete in-memory records -----
    const inMemoryRecords = this.getRecordsForSubject(request.orgId, request.subjectId);
    for (const record of inMemoryRecords) {
      const policy = this.policies.get(record.retentionPolicyId);

      if (record.legalHold || policy?.legalHoldEnabled) {
        retainedCount++;
        retentionReasons.push(`Record ${record.recordId}: Legal hold`);
        continue;
      }

      if (record.dataCategory === "audit_logs" && policy?.complianceFramework !== "custom") {
        retainedCount++;
        retentionReasons.push(`Record ${record.recordId}: Compliance requirement`);
        continue;
      }

      record.deletedAt = new Date();
      deletedCount++;
    }

    return {
      exportUrl: null,
      exportExpiresAt: null,
      deletedRecords: deletedCount,
      retainedRecords: retainedCount,
      retentionReason: retentionReasons.length > 0 ? retentionReasons.join("; ") : null,
      verificationHash: crypto.createHash("sha256").update(`deleted:${deletedCount}:retained:${retainedCount}`).digest("hex"),
      completedAt: new Date(),
    };
  }

  /**
   * Process access request (right of access)
   */
  private async processAccessRequest(request: DataSubjectRequest): Promise<DataSubjectResult> {
    // Same as export but without download
    return this.processExportRequest(request);
  }

  /**
   * Process restrict request (right to restriction)
   */
  private async processRestrictRequest(request: DataSubjectRequest): Promise<DataSubjectResult> {
    const records = this.getRecordsForSubject(request.orgId, request.subjectId);

    // Mark all records as restricted (legal hold)
    for (const record of records) {
      record.legalHold = true;
    }

    return {
      exportUrl: null,
      exportExpiresAt: null,
      deletedRecords: 0,
      retainedRecords: records.length,
      retentionReason: "Processing restricted per subject request",
      verificationHash: crypto.createHash("sha256").update(`restricted:${records.length}`).digest("hex"),
      completedAt: new Date(),
    };
  }

  /**
   * Get pending DSRs
   */
  getPendingDSRs(orgId: string): DataSubjectRequest[] {
    return Array.from(this.requests.values())
      .filter(r => r.orgId === orgId && r.status === "pending");
  }

  /**
   * Get overdue DSRs
   */
  getOverdueDSRs(orgId: string): DataSubjectRequest[] {
    const now = new Date();
    return Array.from(this.requests.values())
      .filter(r => r.orgId === orgId && r.status === "pending" && r.deadline < now);
  }

  // ============================================================================
  // COMPLIANCE REPORTING
  // ============================================================================

  /**
   * Generate compliance report
   */
  generateComplianceReport(params: {
    orgId: string;
    framework: RetentionPolicy["complianceFramework"];
    startDate: Date;
    endDate: Date;
    generatedBy: string;
  }): ComplianceReport {
    const records = Array.from(this.records.values())
      .filter(r => r.orgId === params.orgId);

    const dsrs = Array.from(this.requests.values())
      .filter(r => r.orgId === params.orgId && 
        r.requestedAt >= params.startDate && 
        r.requestedAt <= params.endDate);

    // Calculate metrics
    const totalRecords = records.length;
    const expiredRecords = records.filter(r => r.expiresAt < new Date()).length;
    const archivedRecords = records.filter(r => r.archivedAt).length;
    const deletedRecords = records.filter(r => r.deletedAt).length;

    const completedDSRs = dsrs.filter(r => r.status === "completed");
    const responseTimes = completedDSRs
      .filter(r => r.completedAt)
      .map(r => r.completedAt!.getTime() - r.requestedAt.getTime());
    const averageResponseTime = responseTimes.length > 0
      ? responseTimes.reduce((a, b) => a + b, 0) / responseTimes.length / (24 * 60 * 60 * 1000)
      : 0;

    // Identify issues
    const issues: string[] = [];
    const recommendations: string[] = [];

    const overdueDSRs = this.getOverdueDSRs(params.orgId);
    if (overdueDSRs.length > 0) {
      issues.push(`${overdueDSRs.length} overdue DSR(s) require immediate attention`);
      recommendations.push("Process overdue DSRs immediately to avoid compliance violations");
    }

    if (averageResponseTime > 25) {
      issues.push(`Average DSR response time (${averageResponseTime.toFixed(1)} days) approaching deadline`);
      recommendations.push("Implement automated DSR processing to reduce response time");
    }

    const policiesWithoutLegalHold = this.getPolicies(params.orgId)
      .filter(p => !p.legalHoldEnabled && p.dataCategory === "audit_logs");
    if (policiesWithoutLegalHold.length > 0) {
      recommendations.push("Consider enabling legal hold on audit log policies for compliance");
    }

    return {
      reportId: crypto.randomUUID(),
      orgId: params.orgId,
      framework: params.framework,
      reportPeriod: { start: params.startDate, end: params.endDate },
      totalRecords,
      expiredRecords,
      archivedRecords,
      deletedRecords,
      totalDSRs: dsrs.length,
      completedDSRs: completedDSRs.length,
      averageResponseTime,
      issues,
      recommendations,
      generatedAt: new Date(),
      generatedBy: params.generatedBy,
    };
  }

  // ============================================================================
  // AUDIT LOG
  // ============================================================================

  /**
   * Get audit log
   */
  getAuditLog(params?: {
    orgId?: string;
    subjectId?: string;
    startDate?: Date;
    endDate?: Date;
  }): typeof this.auditLog {
    let log = [...this.auditLog];

    if (params?.subjectId) {
      log = log.filter(e => e.subjectId === params.subjectId);
    }

    if (params?.startDate) {
      log = log.filter(e => e.timestamp >= params.startDate!);
    }

    if (params?.endDate) {
      log = log.filter(e => e.timestamp <= params.endDate!);
    }

    return log;
  }

  // ============================================================================
  // PRIVATE HELPERS
  // ============================================================================

  /**
   * Update a DSR record in the database.
   */
  private async updateDSRInDb(
    requestId: string,
    fields: { status?: string; processedBy?: string; completedAt?: Date | null; result?: string | null; notes?: string },
  ): Promise<void> {
    try {
      const db = await getDb();
      await db
        .update(dataSubjectRequests)
        .set({
          ...(fields.status !== undefined && { status: fields.status }),
          ...(fields.processedBy !== undefined && { processedBy: fields.processedBy }),
          ...(fields.completedAt !== undefined && { completedAt: fields.completedAt }),
          ...(fields.result !== undefined && { result: fields.result }),
          ...(fields.notes !== undefined && { notes: fields.notes }),
          updatedAt: new Date(),
        })
        .where(eq(dataSubjectRequests.id, requestId));
    } catch (err) {
      this.logAudit("DSR_DB_UPDATE_FAILED", "system", `Failed to update DSR ${requestId} in DB: ${(err as Error).message}`, null);
    }
  }

  private logAudit(action: string, actor: string, details: string, subjectId: string | null): void {
    this.auditLog.push({
      timestamp: new Date(),
      action,
      actor,
      details,
      subjectId,
    });
  }

  /**
   * Clear all data (for testing)
   */
  clear(): void {
    this.policies.clear();
    this.requests.clear();
    this.records.clear();
    this.auditLog = [];
  }
}

// ============================================================================
// SINGLETON INSTANCE
// ============================================================================

export const dataRetentionService = new DataRetentionService();

